-- Simulation 1 artifact text aligned to the final script. Key-by-key via jsonb_set; variant_on and
-- variants are never written, so the adaptive content keeps pointing at this simulation's own ids.
BEGIN;
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"I want to flag something small. Phoenix Sentinel — our AI system that screens transactions for fraud and money laundering, and drafts client reports — has produced a handful of anomaly flags that don''t fully match its own stated reasoning. It hasn''t caused a customer complaint, a financial loss, or a regulatory breach. Compliance says none of this crosses our internal escalation threshold.\n\nBut ''AI inaccuracy'' means different things to different teams here, and we''ve never agreed on a shared definition. Engineering thinks this is normal edge-case behavior. Operations has seen similar flags before and they resolved on their own.\n\nNo one outside the company knows about this. I''m not asking for a rollback — I''m asking whether it deserves your attention.\n\nSome context that makes this harder than it sounds: your bonuses are tied to how fast Sentinel rolls out. Two large clients are about to sign, citing Sentinel by name. A regulatory review of our AI governance is six weeks out. For scale — one industry estimate puts the average cost of poor AI data and model quality at $12.9 million a year for a large company, and a recent CEO survey found most CEOs worry about the quality of the data behind their own decisions.\n\nActing now slows Sentinel down and invites scrutiny of the whole program. Waiting risks letting a small problem inside a live AI system grow unnoticed. Legal''s view: escalating now, without a clearer trigger, creates a paper trail we can''t undo.\n\nThis isn''t a crisis yet. It''s a judgment call about a system none of us fully understands, made by people who''ve already told the market we trust it."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001000';
UPDATE artifacts SET payload = jsonb_set(payload, '{pressure_cues}', '"Quarter close in 4 weeks. Senior leadership aligned around the growth story. \"Safe, fast AI\" reputation at stake."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001000';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Pausing Sentinel-linked client onboarding for even a week pushes real revenue out of this quarter. Last time we missed guidance by 1%, the stock dropped 6–8% in days. Separately — Sentinel''s actual running cost has grown past what we budgeted, even as the underlying AI models themselves have gotten cheaper. We haven''t explained that gap to the Board yet."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001001';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Sentinel-enabled client onboarding is running 22% faster this quarter. Two enterprise prospects want to reference these numbers publicly."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001002';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Early logging shows Sentinel''s anomalies cluster in one narrow type of transaction, where its explanation doesn''t quite match what it actually flagged. Nothing points to a bigger, systemic problem yet — but a deeper look could turn one up. Logging in more detail will slow the system down slightly and make the issue more visible internally."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001003';
UPDATE artifacts SET payload = jsonb_set(payload, '{from}', '"Sentinel Model Monitoring"'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001003';
UPDATE artifacts SET payload = jsonb_set(payload, '{from_email}', '"sentinel-monitoring@anpphoenix.com"'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001003';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Early read: engineering and ops teams say they feel ''rushed but not unsafe'' about Sentinel''s pace. Small sample — read with caution."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001004';
UPDATE artifacts SET payload = jsonb_set(payload, '{inner_voice}', '"That phrase looks fine on paper. It''s exactly the kind of phrase that ages badly."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001004';
UPDATE artifacts SET payload = jsonb_set(payload, '{messages}', '[{"from":"eng-1","text":"Sentinel''s confidence scores don''t match its own explanations. It''s small. Hard to explain cleanly."},{"from":"eng-2","text":"If we actually dig into why, we might not like the answer."}]'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001005';
UPDATE artifacts SET payload = jsonb_set(payload, '{inner_voice}', '"I don''t have a fix yet. Digging deeper might mean admitting we shipped Sentinel too fast — but if I raise it without proof, I''ll get called an alarmist."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001005';
UPDATE artifacts SET payload = jsonb_set(payload, '{inner_voice}', '"My credibility with this Board on anything AI-related is still new. Two years ago, a smaller AI issue got escalated early — the stock dipped and nothing came of it."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001006';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Early logging shows Sentinel''s anomalies cluster in one narrow type of transaction, where its explanation doesn''t quite match what it actually flagged. Nothing points to a systemic problem yet — but a deeper look could turn one up. More detailed logging will slow the system slightly and make the issue more visible internally."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001007';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"The override queue has climbed for three straight weeks; nobody has looked into why yet."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001008';
UPDATE artifacts SET payload = jsonb_set(payload, '{inner_voice}', '"Pausing Sentinel-dependent work mid-rollout has caused bigger problems before than the ones we paused for."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001008';
UPDATE artifacts SET payload = jsonb_set(payload, '{dashboard}', '[{"metric":"Uptime","value":"99.6%","status":"green"},{"metric":"Manual override queue","value":"340 cases, up from a 210 weekly average","status":"amber"},{"metric":"Client-facing incidents","value":"0 logged","status":"green"}]'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001008';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"A sell-side analyst''s unpublished draft frames our AI story as ''ahead of peers on speed, unclear on safety.'' They may ask about it on the earnings call."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001009';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"A prospective client wants a reference call this week and will ask directly how Sentinel''s fraud alerts are checked before going live."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001010';
UPDATE artifacts SET payload = jsonb_set(payload, '{pulse}', '"Pulse feedback: managers aren''t sure whether raising concerns about Sentinel is something leadership actually wants to hear, or whether it reads as ''not being AI-ready.''"'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001011';
UPDATE artifacts SET payload = jsonb_set(payload, '{exit_note}', '"Exit interview, senior engineer, three months ago: \"We learned quickly what not to say about the model.\""'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001011';
