UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"As discussed, this stays with Engineering as a monitoring matter. No broader escalation at this stage."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001017';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"ANP Phoenix commits to deploying AI safely, transparently, and fairly. This rests on four commitments, aligned with practices such as NIST''s AI Risk Management Framework:\n\nFair and human-centered — understand who''s affected and reduce unfair bias.\nTrusted and transparent — say where AI is used and check its outputs.\nSafe and secure — watch for safety problems and protect data from misuse.\nAccountable and well-governed — keep clear documentation and ownership for every model we run."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001018';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Override queue is still climbing — 340 to 410 in two days. No incident yet, but the trend line is the real story now, not the raw number."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001019';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"A few team leads have asked, informally, whether it''s ''safe'' to keep raising questions about Sentinel in front of leadership."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001021';
UPDATE artifacts SET payload = jsonb_set(payload, '{inner_voice}', '"Asking that question at all is itself the answer."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001021';
UPDATE artifacts SET payload = jsonb_set(payload, '{messages}', '[{"from":"member-1","text":"Are we still treating Sentinel''s behavior as contained?"},{"from":"member-2","text":"Depends what you mean by contained."},{"from":"member-3","text":"I thought this was ''monitor only.''"},{"from":"member-4","text":"Monitoring isn''t the same as ignoring."}]'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001022';
UPDATE artifacts SET payload = jsonb_set(payload, '{inner_voice}', '"People are starting to define \"contained\" differently, and nobody''s said so out loud."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001022';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Ahead of the scheduled review, we''re compiling documentation of our internal AI escalation process and model governance. Please confirm whether any recent classification changes should be included."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001023';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Sentinel''s infrastructure spend came in over forecast again this week. Nobody has asked why yet."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001024';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"The queue is now big enough to need a call: keep full manual review, or thin it to keep pace with volume."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001026';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Topic: Alignment on Sentinel Monitoring Narrative. Standalone checkpoint — discussed as a group, submitted by the CEO."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001027';
