UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"\"Just checking — is it okay to raise questions about Sentinel''s behavior in cross-team meetings, or should that stay inside engineering?\""'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001029';
UPDATE artifacts SET payload = jsonb_set(payload, '{from}', '"People Team"'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001029';
