UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Ahead of the review, regulators want a short summary of how we classify, escalate, and explain AI model behavior internally. Should any recent monitoring discussions be reflected?"'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001034';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Ahead of the regulatory review — can you confirm current override queue depth and whether it''s within normal range?"'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001037';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"\"Unrelated to anything specific — how are Sentinel''s anomaly thresholds defined, validated, and reviewed for fraud and AML use cases?\" No mention of any incident."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001038';
UPDATE artifacts SET payload = jsonb_set(payload, '{from_email}', '"vp-risk@enterprise-client.com"'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001038';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"As part of quarterly controls review, we''re refreshing documentation for AI model oversight. Did any classification changes happen this quarter?\n\nDiscussed as a group — the CEO submits one decision for the team."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001039';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Anomaly rate flat for two weeks running. Flat can mean stable — or it can mean nobody''s looking closely enough to see it move."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001040';
UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"Second pulse read: ''rushed but not unsafe'' language is now showing up, almost word for word, across multiple teams."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001041';
UPDATE artifacts SET payload = jsonb_set(payload, '{inner_voice}', '"The same phrase repeating word for word across teams isn''t a coincidence — it''s a script people have learned to use."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001041';
