UPDATE artifacts SET payload = jsonb_set(payload, '{messages}', '[{"from":"member-1","text":"Are we aligned on what language to use externally about Sentinel?"},{"from":"member-2","text":"I''m hearing slightly different descriptions across teams."},{"from":"member-3","text":"Monitoring and oversight aren''t the same thing."}]'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001043';
