UPDATE artifacts SET payload = jsonb_set(payload, '{body}', '"During routine review, regulators asked how early Sentinel anomaly discussions were documented, kept, and made explainable. No concern expressed."'::jsonb, true) WHERE artifact_id = 'a1000000-0000-4000-a001-000000001055';
